// plain blocking code, one cheap virtual thread per checkout
List<Receipt> checkoutAll(List<Basket> baskets) throws Exception {
    try (ExecutorService perTask = Executors.newVirtualThreadPerTaskExecutor()) {
        List<Future<Receipt>> futures = new ArrayList<>();
        for (Basket b : baskets) futures.add(perTask.submit(() -> checkout(b)));
        List<Receipt> receipts = new ArrayList<>();
        for (Future<Receipt> f : futures) receipts.add(f.get());
        return receipts;
    }
}

Receipt checkout(Basket b) {
    Stock stock = warehouse.reserve(b);      // an ordinary blocking call over the network
    Payment paid = bank.charge(b, stock);
    return orders.save(b, paid);             // an ordinary database call
}

