// suspend functions: the compiler turns them into steps it can pause between
suspend fun checkoutAll(baskets: List<Basket>): List<Receipt> = coroutineScope {
    baskets.map { b -> async { checkout(b) } }.awaitAll()
}

suspend fun checkout(b: Basket): Receipt {
    val stock = warehouse.reserve(b)         // must itself suspend to free the thread
    val paid = bank.charge(b, stock)
    return orders.save(b, paid)              // a blocking database call here would block a real thread
}

